// ===========================================================================

pub struct ContextBudgetTool;

impl ContextBudgetTool {
    pub fn new() -> Self {
        Self
    }
}

#[async_trait]
impl McpTool for ContextBudgetTool {
    fn name(&self) -> &'static str {
        "context_budget"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Estimate token usage from optional conversation text + turn count using offline heuristics; \
                 compare to an approximate model context limit and get a compaction recommendation. No API calls."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "model": {
                        "type": "string",
                        "description": "Model name hint for context window size (default: claude-sonnet-4).",
                        "default": "claude-sonnet-4"
                    },
                    "context_window": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Explicit context-window size in tokens — overrides the model→limit lookup. Pass 1000000 for long-context-beta (opus-4.x / sonnet-4.x @ 1M) sessions; the model name alone can't reveal the 200K-vs-1M SKU. Precedence: this arg > AGENT_BRIDGE_CONTEXT_WINDOW env > model default."
                    },
                    "conversation_turns": {
                        "type": "integer",
                        "minimum": 0,
                        "description": "When transcript is unavailable, each turn adds a coarse token guess.",
                        "default": 0
                    },
                    "text_sample": {
                        "type": "string",
                        "description": "Optional excerpt / transcript sample to token-estimate (mixed EN/CJK heuristic)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let model = args
            .get("model")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("claude-sonnet-4");
        let turns = args
            .get("conversation_turns")
            .and_then(|v| v.as_u64())
            .unwrap_or(0);
        let text = args
            .get("text_sample")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        // Window precedence: explicit arg > AGENT_BRIDGE_CONTEXT_WINDOW env >
        // conservative model default (see context_pressure_estimate / #1758).
        let explicit_window = args
            .get("context_window")
            .or_else(|| args.get("model_limit"))
            .and_then(|v| v.as_u64());
        let (limit, limit_source) =
            resolve_context_window(explicit_window, env_context_window(), model);
        let estimated = estimated_usage_tokens(text, turns);
        let pct_raw = if limit == 0 {
            0.0
        } else {
            (estimated as f64 / limit as f64) * 100.0
        };
        let pct_used = (pct_raw * 10.0).round() / 10.0;
        let recommendation = budget_recommendation(pct_raw);
        Ok(ToolResult::json_text(&json!({
            "model_hint": model,
            "model_limit": limit,
            "model_limit_source": limit_source,
            "estimated_tokens_used": estimated,
            "pct_used": pct_used,
            "recommendation": recommendation,
            "heuristic_note": "Offline estimate only; actual tokenizer usage varies.",
        })))
    }
}

// ===========================================================================
//        context_pressure_estimate — L6 P3 metacognition probe
// ===========================================================================

/// L6 P3 — `context_pressure_estimate` MCP tool.
///
/// Companion to `context_budget` but framed for **introspection**: the
/// assistant reads its own context-window pressure as a categorical
/// fatigue tier (`fresh|engaged|strained|saturated`) plus distance to
/// compaction. Roadmap §3 L6 P3 (~0.3d).
///
/// Backed entirely by the existing offline `context_budget` heuristic —
/// no API calls, no LLM judge. Cheap enough to call at session
/// bootstrap + per-turn if desired.
pub struct ContextPressureEstimateTool;

impl ContextPressureEstimateTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for ContextPressureEstimateTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl McpTool for ContextPressureEstimateTool {
    fn name(&self) -> &'static str {
        "context_pressure_estimate"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "L6 P3 metacognition probe — read the assistant's own \
                 context-window pressure as a categorical fatigue tier (fresh / \
                 engaged / strained / saturated) plus distance-to-compaction. \
                 Backed by the same offline heuristic as `context_budget` but \
                 surfaced for introspective decisions (\"should I compact \
                 before starting another long task?\"). No API calls."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "model": {
                        "type": "string",
                        "description": "Model name hint for context window size (default: claude-sonnet-4).",
                        "default": "claude-sonnet-4"
                    },
                    "context_window": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Explicit context-window size in tokens — overrides the model→limit lookup. Use on long-context-beta sessions (e.g. opus-4.x / sonnet-4.x @ 1M): the model name alone cannot reveal the 200K-vs-1M SKU, so omitting this defaults to a conservative 200K and inflates pressure up to 5×. Pass 1000000 when on the 1M beta. Precedence: this arg > AGENT_BRIDGE_CONTEXT_WINDOW env > model default (set the env once machine-wide to avoid per-call args)."
                    },
                    "conversation_turns": {
                        "type": "integer",
                        "minimum": 0,
                        "description": "Turn count for coarse-overhead estimate when no transcript is available.",
                        "default": 0
                    },
                    "text_sample": {
                        "type": "string",
                        "description": "Optional transcript / excerpt sample for token-estimation (mixed EN/CJK heuristic)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        use crate::context_budget::{
            budget_recommendation, env_context_window, estimated_usage_tokens, fatigue_tier,
            model_supports_1m_beta, resolve_context_window,
        };
        let model = args
            .get("model")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("claude-sonnet-4");
        let turns = args
            .get("conversation_turns")
            .and_then(|v| v.as_u64())
            .unwrap_or(0);
        let text_raw = args
            .get("text_sample")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let text_sample_provided = !text_raw.is_empty();

        // Resolve the window: explicit caller arg > AGENT_BRIDGE_CONTEXT_WINDOW
        // env (machine-level truth, survives a client stripping the unknown
        // arg) > conservative model default. `model_limit` accepted as a
        // defensive alias for callers following the orchestrate_scan hint.
        let explicit_window = args
            .get("context_window")
            .or_else(|| args.get("model_limit"))
            .and_then(|v| v.as_u64());
        let (limit, limit_source) =
            resolve_context_window(explicit_window, env_context_window(), model);
        // Flag the 1M ambiguity only when we fell all the way back to the
        // model default AND the model is a long-context-beta family — tells
        // the caller to set the window (guards the #1758 5× inflation).
        let one_m_beta_possible = limit_source == "model_default" && model_supports_1m_beta(model);
        let estimated = estimated_usage_tokens(text_raw, turns);
        let pct_raw = if limit == 0 {
            0.0
        } else {
            (estimated as f64 / limit as f64) * 100.0
        };
        let pct_used = (pct_raw * 10.0).round() / 10.0;
        let tier = fatigue_tier(pct_raw);
        let recommendation = budget_recommendation(pct_raw);
        // Distance to soft compaction trigger (urgent_handoff at 80%).
        // Clamped at 0 — we never report "negative distance" since past
        // the threshold the model has already overrun the safe zone.
        let soft_trigger = (limit as f64 * 0.80) as u64;
        let distance_to_compaction = soft_trigger.saturating_sub(estimated);

        // L6 P3 dogfood 5/13 + 5/19: no-sample reading systematically
        // under-counted. Flag confidence so the caller can weight the
        // tier accordingly rather than treating heuristic-only as ground
        // truth.
        let confidence = if text_sample_provided { "high" } else { "low" };
        let mut note = String::from(if text_sample_provided {
            "Estimate uses turn × per-turn guess + actual sample tokens + system baseline."
        } else {
            "No text_sample passed — estimate is heuristic-only and may under-count tool-heavy turns. Pass `text_sample` (recent transcript excerpt) for higher confidence."
        });
        if one_m_beta_possible {
            note.push_str(
                " NOTE: limit defaulted to 200K but this is a long-context-beta family (opus-4.x / sonnet-4.x); if the session runs the 1M beta, pass context_window=1000000 (or set AGENT_BRIDGE_CONTEXT_WINDOW=1000000 once, machine-wide — survives clients that strip the arg) — otherwise pct_used / fatigue_tier are inflated up to 5×.",
            );
        }

        Ok(ToolResult::json_text(&json!({
            "model_hint": model,
            "model_limit": limit,
            "model_limit_source": limit_source,
            "long_context_beta_possible": one_m_beta_possible,
            "estimated_tokens_used": estimated,
            "pct_used": pct_used,
            "fatigue_tier": tier,
            "distance_to_compaction_tokens": distance_to_compaction,
            "recommendation": recommendation,
            "text_sample_provided": text_sample_provided,
            "confidence": confidence,
            "note": note,
            "heuristic_note": "Offline estimate; actual tokenizer usage varies. Tier bands per roadmap §3 L6 P3.",
        })))
    }
}

// ===========================================================================
//        tool_call_attention_report — L6 P2 metacognition probe
// ===========================================================================

/// L6 P2 — Result of `tool_call_attention_report`. Pure data; the
/// MCP tool wraps this in a JSON response. Exposed `pub` (not just
/// crate-local) so cron jobs and integration tests can use the same
/// aggregator from outside this module.
#[derive(Debug, serde::Serialize)]
pub struct AttentionReport {
    pub window_secs: i64,
    pub high_yield_threshold_bytes: u32,
    pub followup_window_secs: i64,
    pub total_calls: usize,
    pub high_yield_calls: usize,
    pub followed_up_calls: usize,
    pub ignored_calls: usize,
    pub followed_up_ratio: f64,
    pub ignored: Vec<AttentionIgnoredRow>,
    pub top_yield: Vec<AttentionYieldRow>,
}

#[derive(Debug, serde::Serialize)]
pub struct AttentionIgnoredRow {
    pub ts: i64,
    pub tool_name: String,
    pub result_size: u32,
}

#[derive(Debug, serde::Serialize)]
pub struct AttentionYieldRow {
    pub ts: i64,
    pub tool_name: String,
    pub result_size: u32,
    pub followed_up: bool,
}

/// **L6 P2** — pure aggregator for the attention report.
///
/// Given a chronologically-sorted `calls` vector + thresholds, returns
/// a structured report. Pure for testability; the MCP tool wires this
/// to live store data.
///
/// Heuristic for "follow-up": after a high-yield call at time `t`, did
/// ANY other tool call appear in the same call list within
/// `followup_window_secs`? This is a structural proxy for "the agent
/// did something after seeing the result"; it doesn't prove the result
/// was *used*, but a missing follow-up strongly suggests the result
/// was ignored.
pub fn compute_attention_report(
    calls: &[ab_store::McpToolCallRow],
    window_secs: i64,
    high_yield_threshold_bytes: u32,
    followup_window_secs: i64,
) -> AttentionReport {
    // Filter to high-yield successful calls (errors are pre-filtered out
    // by spec: ignored-but-failed is a different signal).
    let high_yield: Vec<&ab_store::McpToolCallRow> = calls
        .iter()
        .filter(|c| c.ok)
        .filter(|c| {
            c.result_size
                .map(|s| s >= high_yield_threshold_bytes)
                .unwrap_or(false)
        })
        .collect();

    let mut followed_up_count = 0usize;
    let mut ignored: Vec<AttentionIgnoredRow> = Vec::new();
    let mut top_yield_rows: Vec<AttentionYieldRow> = Vec::new();

    for hy in &high_yield {
        // Did any DIFFERENT call (different ts OR different tool name)
        // appear in (hy.ts, hy.ts + followup_window_secs]? "Different"
        // protects against the same call counting itself when ts ties.
        let cutoff_end = hy.ts + followup_window_secs;
        let has_followup = calls.iter().any(|c| {
            c.ts > hy.ts && c.ts <= cutoff_end && (c.ts != hy.ts || c.tool_name != hy.tool_name)
        });
        let result_size = hy.result_size.unwrap_or(0);
        if has_followup {
            followed_up_count += 1;
        } else {
            ignored.push(AttentionIgnoredRow {
                ts: hy.ts,
                tool_name: hy.tool_name.clone(),
                result_size,
            });
        }
        top_yield_rows.push(AttentionYieldRow {
            ts: hy.ts,
            tool_name: hy.tool_name.clone(),
            result_size,
            followed_up: has_followup,
        });
    }

    // Sort top_yield by result_size DESC (most ROI-bearing first); take
    // top 20 for the report payload.
    top_yield_rows.sort_by(|a, b| b.result_size.cmp(&a.result_size));
    top_yield_rows.truncate(20);
    // Sort ignored by result_size DESC — biggest unused payload first.
    ignored.sort_by(|a, b| b.result_size.cmp(&a.result_size));
    ignored.truncate(20);

    let total = high_yield.len();
    let followed_up_ratio = if total == 0 {
        0.0
    } else {
        followed_up_count as f64 / total as f64
    };

    AttentionReport {
        window_secs,
        high_yield_threshold_bytes,
        followup_window_secs,
        total_calls: calls.len(),
        high_yield_calls: total,
        followed_up_calls: followed_up_count,
        ignored_calls: total - followed_up_count,
        followed_up_ratio,
        ignored,
        top_yield: top_yield_rows,
    }
}

/// L6 P2 — MCP tool that surfaces the attention report.
pub struct ToolCallAttentionReportTool {
    hub: Hub,
}

impl ToolCallAttentionReportTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for ToolCallAttentionReportTool {
    fn name(&self) -> &'static str {
        "tool_call_attention_report"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "L6 P2 metacognition probe — for the recent window, \
                 summarize which high-yield (≥N bytes result) tool calls had \
                 follow-up activity within K seconds (proxy for 'I used the \
                 answer') vs which had none (proxy for 'I asked for X then \
                 ignored the answer'). Backed by mcp_tool_calls telemetry; \
                 no LLM, no transcript access. Tuning targets: \
                 `high_yield_threshold_bytes` (default 2500 ≈ 10KB) + \
                 `followup_window_secs` (default 600 = 10min)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 86400,
                        "default": 7200,
                        "description": "Lookback for tool-call telemetry. Default 7200s (2h ≈ recent session)."
                    },
                    "high_yield_threshold_bytes": {
                        "type": "integer",
                        "minimum": 100,
                        "default": 2500,
                        "description": "result_size >= this is considered high-yield (worth following up on)."
                    },
                    "followup_window_secs": {
                        "type": "integer",
                        "minimum": 30,
                        "maximum": 3600,
                        "default": 600,
                        "description": "After a high-yield call, look for ANY other call within this window. None → 'ignored'."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(7200)
            .clamp(60, 86_400);
        let threshold = args
            .get("high_yield_threshold_bytes")
            .and_then(|v| v.as_u64())
            .unwrap_or(2500)
            .min(u32::MAX as u64) as u32;
        let followup = args
            .get("followup_window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(600)
            .clamp(30, 3600);

        // Fetch row-level telemetry. Cap at 2000 to bound report cost
        // even on noisy sessions; matches the trait's hard cap.
        let calls = match store.recent_mcp_tool_calls(window_secs, 2000).await {
            Ok(c) => c,
            Err(e) => {
                return Ok(ToolResult::error(format!(
                    "recent_mcp_tool_calls failed: {e}"
                )));
            }
        };

        let report = compute_attention_report(&calls, window_secs, threshold, followup);
        let payload = serde_json::to_value(&report).unwrap_or_else(|_| json!({}));
        Ok(ToolResult::json_text(&payload))
    }
}

// ===========================================================================
//        embed_text — Phase 2.1 raw encoder exposure for external apps
// ===========================================================================

/// Pure helper — pick raw inner encoder per Phase 2.1 precedence,
/// independent of `ab_store::default_backend()` (which may be wrapped
/// by `SeedBackend` when v22 substrate is installed; here we want raw
/// 384-d MiniLM output with no substrate perception side effect).
///
/// Mirrors `seed_bridge::select_inner_kind()` so wrap and raw paths
/// agree on which encoder produces the vectors.
fn select_raw_encoder_kind() -> String {
    std::env::var("AGENT_BRIDGE_EMBED_BACKEND")
        .ok()
        .map(|s| s.to_lowercase())
        .filter(|s| s == "hash" || s == "onnx")
        .unwrap_or_else(|| "onnx".to_string())
}

fn build_raw_encoder() -> Arc<dyn ab_store::EmbeddingBackend> {
    match select_raw_encoder_kind().as_str() {
        "hash" => Arc::new(ab_store::HashBackend),
        // "onnx" or fallthrough — OnnxBackend carries its own hash
        // fallback on model-load failure, so unknown values are
        // safe-by-default.
        _ => Arc::new(ab_store::OnnxBackend),
    }
}

/// **Phase 2.1 / onsen-hd integration** — `embed_text` MCP tool.
///
/// Exposes the raw inner sentence encoder (`all-MiniLM-L6-v2` 384-d via
/// `fastembed`, hash fallback on model-load failure) so external apps
/// can build their own grids / indexes without touching v22 substrate
/// state. Companion HTTP route `POST /embed` ships on daemon-http for
/// non-MCP clients (Unity / Unreal / Godot / Web).
///
/// Returns raw inner output — does NOT feed substrate perception. Use
/// `memory_save` for substrate-aware embedding flow.
pub struct EmbedTextTool;

impl EmbedTextTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for EmbedTextTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl McpTool for EmbedTextTool {
    fn name(&self) -> &'static str {
        "embed_text"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Raw sentence-encoder pass-through — returns 384-d \
                `all-MiniLM-L6-v2` MiniLM embedding (hash fallback on model-load \
                failure). Exposes Phase 2.1 inner encoder for external apps (e.g. \
                game NPC AI, custom indexers) that need encoder semantics WITHOUT \
                feeding v22 substrate perception. Companion HTTP route POST /embed \
                on daemon-http for non-MCP clients."
                .into(),
            input_schema: json!({
                "type": "object",
                "required": ["text"],
                "properties": {
                    "text": {
                        "type": "string",
                        "description": "Text to encode. Empty input returns zero/default vector of dim()."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let text = args.get("text").and_then(|v| v.as_str()).unwrap_or("");
        let backend = build_raw_encoder();
        let vec = backend.embed(text);
        Ok(ToolResult::json_text(&json!({
            "embedding": vec,
            "backend": backend.name(),
            "dim": backend.dim(),
        })))
    }
}

