/// Per-tool surface-area tier for `AGENT_BRIDGE_TOOL_PROFILE` filtering.
///
/// Some MCP clients cap or defer large live tool lists. Tiers let constrained
/// clients choose the small "essential" surface while richer frontends keep
/// the broader standard registry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    /// Always registered. The smallest set that lets a typical interactive
    /// Claude session work end-to-end (memory navigation, terminal control,
    /// agent_spawn, plan/worktree basics, shell_exec, session lifecycle
    /// bootstrap/finalize).
    Essential,
    /// Default-on. Adds hook-friendly + multi-agent + maintenance ops:
    /// memory consolidation, session curation, agent inbox, codebase index,
    /// terminal_read_blocks (Warp), notify.
    Standard,
    /// Default-off. Specialty surfaces: browser_*, warp_*, oz_*, MCP
    /// introspection (mcp_recent_errors / mcp_call_stats / mcp_config_audit),
    /// memory admin (export/import/consolidate/auto_curate/graph_export),
    /// osc_parse, hook_status, context_budget. Enable explicitly with
    /// `AGENT_BRIDGE_TOOL_PROFILE=all` (or pick what you need via finer
    /// gates in the future).
    Niche,
}

#[derive(Debug, Clone, Copy)]
pub enum ToolProfile {
    Essential,
    Compact,
    Standard,
    All,
}

impl ToolProfile {
    pub fn from_env() -> Self {
        Self::from_value(std::env::var("AGENT_BRIDGE_TOOL_PROFILE").ok().as_deref())
    }

    fn from_value(value: Option<&str>) -> Self {
        match value.map(|s| s.trim().to_lowercase()).as_deref() {
            Some("essential") | Some("minimal") => Self::Essential,
            Some("compact") | Some("essential-plus") => Self::Compact,
            Some("all") | Some("full") => Self::All,
            _ => Self::Standard,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Self::Essential => "essential",
            Self::Compact => "compact",
            Self::Standard => "standard",
            Self::All => "all",
        }
    }

    pub fn includes(self, tier: Tier) -> bool {
        match (self, tier) {
            (Self::All, _) => true,
            (Self::Standard, Tier::Niche) => false,
            (Self::Standard, _) => true,
            (Self::Essential | Self::Compact, Tier::Essential) => true,
            (Self::Essential | Self::Compact, _) => false,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ToolSet {
    Profile,
    CodexEssential,
    CodexLean,
    ClaudeStandard,
    GeminiLean,
    HookLifecycle,
    AllDev,
}

impl ToolSet {
    fn label(self) -> &'static str {
        match self {
            Self::Profile => "profile",
            Self::CodexEssential => "codex-essential",
            Self::CodexLean => "codex-lean",
            Self::ClaudeStandard => "claude-standard",
            Self::GeminiLean => "gemini-lean",
            Self::HookLifecycle => "hook-lifecycle",
            Self::AllDev => "all-dev",
        }
    }

    fn from_value(value: Option<&str>) -> Option<Self> {
        match value.map(normalize_tool_policy_value).as_deref() {
            Some("profile") | Some("legacy") => Some(Self::Profile),
            Some("codex-essential") | Some("codex") => Some(Self::CodexEssential),
            Some("codex-lean") | Some("codex-minimal") => Some(Self::CodexLean),
            Some("claude-standard") | Some("claude-code") | Some("claude") => {
                Some(Self::ClaudeStandard)
            }
            Some("gemini-lean") | Some("gemini") => Some(Self::GeminiLean),
            Some("hook-lifecycle") | Some("hooks") | Some("hook") | Some("lifecycle") => {
                Some(Self::HookLifecycle)
            }
            Some("all-dev") | Some("dev") | Some("full-dev") => Some(Self::AllDev),
            _ => None,
        }
    }

    fn extras(self) -> Vec<&'static str> {
        match self {
            Self::CodexEssential => CODEX_ESSENTIAL_GROUPS
                .iter()
                .flat_map(|g| g.iter().copied())
                .chain(CODEX_ESSENTIAL_DIRECT_EXTRAS.iter().copied())
                .collect(),
            _ => Vec::new(),
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct ToolPolicy {
    set: ToolSet,
    profile: ToolProfile,
}

impl ToolPolicy {
    fn from_env() -> Self {
        Self::from_values(
            std::env::var("AGENT_BRIDGE_TOOLSET").ok().as_deref(),
            std::env::var("AGENT_BRIDGE_CLIENT").ok().as_deref(),
            std::env::var("AGENT_BRIDGE_MCP_SOURCE").ok().as_deref(),
            std::env::var("AGENT_BRIDGE_TOOL_PROFILE").ok().as_deref(),
        )
    }

    fn from_values(
        toolset: Option<&str>,
        client: Option<&str>,
        source: Option<&str>,
        profile: Option<&str>,
    ) -> Self {
        let set = ToolSet::from_value(toolset)
            .or_else(|| ToolSet::from_value(client))
            .or_else(|| ToolSet::from_value(source))
            .unwrap_or(ToolSet::Profile);
        let legacy_profile = ToolProfile::from_value(profile);
        let profile = match set {
            ToolSet::Profile => legacy_profile,
            ToolSet::CodexEssential => ToolProfile::Compact,
            ToolSet::CodexLean | ToolSet::GeminiLean => ToolProfile::Essential,
            ToolSet::ClaudeStandard | ToolSet::HookLifecycle => ToolProfile::Standard,
            ToolSet::AllDev => ToolProfile::All,
        };
        Self { set, profile }
    }

    fn label(self) -> &'static str {
        self.set.label()
    }

    fn profile(self) -> ToolProfile {
        self.profile
    }

    /// Tools explicitly whitelisted by this toolset *beyond* what the underlying
    /// `ToolProfile` tier covers. For `codex-essential` this is the IDE bridge
    /// pair plus forum/presence collab tools — they are Tier::Standard/Niche
    /// but exposed anyway so Codex agents can use the cross-process whiteboard.
    /// Returned as `&'static [&'static str]` so capabilities serialization can
    /// surface the list verbatim.
    fn extras(self) -> Vec<&'static str> {
        self.set.extras()
    }

    fn includes(self, tier: Tier, tool_name: &'static str) -> bool {
        match self.set {
            ToolSet::Profile | ToolSet::ClaudeStandard | ToolSet::AllDev => {
                self.profile.includes(tier)
            }
            ToolSet::CodexEssential => codex_essential_tool(tier, tool_name),
            ToolSet::CodexLean => codex_lean_tool(tool_name),
            ToolSet::GeminiLean => gemini_lean_tool(tool_name),
            ToolSet::HookLifecycle => hook_lifecycle_tool(tool_name),
        }
    }
}

fn normalize_tool_policy_value(value: &str) -> String {
    value
        .trim()
        .to_lowercase()
        .replace('_', "-")
        .replace(' ', "-")
}

/// Capability groups — single source of truth for cross-client SHARED tool
/// families that are prone to silent drift. Named-allowlist profiles
/// (codex-essential / codex-lean / …) compose their collab surface from these
/// groups, so a NEW tool added to a group auto-propagates to every profile
/// that includes it. This closes the drift that hid `forum_digest` from codex
/// clients (it was Tier::Standard → auto-visible to Claude profiles, but the
/// codex allowlists listed the other 5 forum tools by name and never gained
/// the 6th). See `lesson_wrapper_clobbered_orphans_real_deploys_2026_05_23`.
///
/// NOTE: this groups only the *cross-client collab core* (forum / presence /
/// ide). Per-client curation of memory/session/pet/etc. subsets stays explicit
/// below — that divergence is INTENTIONAL (token budget), not drift.
mod capgroups {
    /// Forum read surface — list/read/digest. A new forum *read* tool added
    /// here propagates to every profile that exposes forum reads.
    pub const FORUM_READ: &[&str] = &["forum_read", "forum_list_threads", "forum_digest"];
    /// Forum write — posting.
    pub const FORUM_POST: &[&str] = &["forum_post"];
    /// Forum lifecycle management — subscriptions + thread status.
    pub const FORUM_MANAGE: &[&str] = &["forum_subscribe", "forum_set_thread_status"];
    /// Presence registry.
    pub const PRESENCE_ANNOUNCE: &[&str] = &["agent_presence_announce"];
    pub const PRESENCE_LIST: &[&str] = &["agent_presence_list"];
    /// IDE bridge pair.
    pub const IDE: &[&str] = &["ide_snapshot", "ide_command"];

    /// Every tool that belongs to a collab group — used by the drift-guardrail
    /// test to assert no registered forum_*/presence/ide tool is left ungrouped.
    #[cfg(test)]
    pub const ALL_COLLAB: &[&[&str]] = &[
        FORUM_READ,
        FORUM_POST,
        FORUM_MANAGE,
        PRESENCE_ANNOUNCE,
        PRESENCE_LIST,
        IDE,
    ];
}

/// True if `name` is a member of any of the given capability groups.
fn in_groups(name: &str, groups: &[&[&str]]) -> bool {
    groups.iter().any(|g| g.contains(&name))
}

/// Collab groups exposed by the `codex-essential` surface (beyond Essential
/// tier). Single source of truth for both `codex_essential_tool` and
/// `ToolSet::extras` (capabilities surfacing).
const CODEX_ESSENTIAL_GROUPS: &[&[&str]] = &[
    capgroups::IDE,
    capgroups::FORUM_READ,
    capgroups::FORUM_POST,
    capgroups::FORUM_MANAGE,
    capgroups::PRESENCE_ANNOUNCE,
    capgroups::PRESENCE_LIST,
];

/// Codex-essential extras that are intentionally not in the cross-client
/// collab capability groups. Keep these explicit so the group drift guardrails
/// stay about forum/presence/IDE families only.
const CODEX_ESSENTIAL_DIRECT_EXTRAS: &[&str] = &[
    // Avatar observation and sidecar-to-presence bridge: expose the read path
    // plus an explicit sync surface so Codex can inspect Xiao Shu without
    // widening to every Standard tool.
    "avatar_adapter_capabilities",
    "avatar_state_get",
    "avatar_surface_snapshot",
    "avatar_surface_report",
    "avatar_cortex_renderer_snapshot",
    "pet_presence_sync",
    "xiao_shu_action_request",
    // Mobile bridge: compact enough to expose directly during Android
    // install/debug lanes; mutation remains explicit per tool.
    "mobile_list_devices",
    "mobile_current_focus",
    "mobile_screenshot",
    "mobile_health",
    "mobile_ui_snapshot",
    "mobile_logcat_tail",
    "mobile_install_apk",
    "mobile_launch_app",
    "mobile_click",
    "mobile_input_text",
    "mobile_apple_status",
    "mobile_ios_list_devices",
    "mobile_ios_apps",
    "mobile_ios_syslog_tail",
    // Search-ranking diagnostics: read-only graph topology preflight for
    // PageRank-like centrality experiments.
    "memory_graph_topology",
    // BioCortex retrieval side-signal: review-only, explicit candidates only,
    // and runtime-disabled unless AB_BIOCORTEX_RETRIEVAL_SHADOW=1.
    "biocortex_retrieval_shadow",
    // Explicit-link diagnostics: read-only projection of related_keys into
    // candidate graph edges before any write-capable backfill is considered.
    "memory_related_keys_preflight",
    // Graph-hygiene diagnostics: read-only orphan candidate preview. The
    // write-capable memory_link_orphans tool stays out of codex-essential.
    "memory_orphan_candidates",
    "memory_orphan_inventory",
    // Linux Computer Use T9a: read-only desktop structure snapshot for Codex
    // IDE lanes. Mutating desktop actions stay out of this allowlist.
    "desktop_snapshot",
    // Linux Computer Use T9b: non-mutating OCR grounding over caller-provided
    // images. It does not capture screenshots or inject input.
    "vision_grounding_ocr",
    // Linux Computer Use: read-only postflight verifier (the verify/recover leg of
    // the act loop). Never clicks/types; completes the read-only triad with
    // desktop_snapshot + vision_grounding_ocr. Mutating act tools stay out.
    "desktop_verify",
    // macOS adapter feasibility: read-only AX trust/frontmost-window probe.
    // No permission prompt and no host mutation; this is the first local
    // cross-platform SSB runtime probe.
    "macos_ax_probe",
    // macOS adapter verifier: read-only predicate check over the same bounded
    // AX/System Events observation surface as macos_ax_probe.
    "macos_ax_verify",
    // SSB conformance inventory: read-only source/fixture/doc classification.
    // It does not execute live probes or mutate desktop/service state.
    "semantic_bus_adapter_report",
    // SSB live local runtime health: bounded read-only HTTP GETs for daemon-http
    // and Palace graph state. It does not restart services or write memory edges.
    "semantic_bus_runtime_health",
    // SSB runtime conformance snapshot: compact read-only aggregation of adapter
    // evidence plus local runtime health. Platform gaps remain explicit.
    "semantic_bus_runtime_conformance",
    // SSB peer conformance query: read-only multi-node pull over daemon-http
    // runtime-conformance exports. No service restart or graph mutation.
    "semantic_bus_peer_conformance",
    // Local system control API: allowlisted wrapper over ab-system-control.
    // It is audited locally and never accepts arbitrary shell commands.
    "system_control",
    // Remote session steering: a Codex orchestrator (which already carries
    // agent_spawn + agent_session_*) can launch/drive/observe long-lived agents
    // in named tmux sessions and roll up a worker blackboard.
    "agent_steer_launch",
    "agent_steer_drive",
    "agent_steer_capture",
    "agent_steer_list",
    "agent_steer_kill",
    "agent_orchestrate_scan",
];

fn codex_essential_tool(tier: Tier, tool_name: &str) -> bool {
    matches!(tier, Tier::Essential)
        || in_groups(tool_name, CODEX_ESSENTIAL_GROUPS)
        || CODEX_ESSENTIAL_DIRECT_EXTRAS.contains(&tool_name)
}

fn codex_lean_tool(tool_name: &str) -> bool {
    // Collab core via groups (gains forum_digest automatically); per-client
    // curated non-collab tools stay explicit (intentional token-budget choice).
    in_groups(
        tool_name,
        &[
            capgroups::FORUM_READ,
            capgroups::FORUM_POST,
            capgroups::PRESENCE_LIST,
        ],
    ) || matches!(
        tool_name,
        "capabilities"
            | "mcp_dispatch_audit"
            | "mcp_lifecycle_digest"
            | "readiness_audit"
            | "event_spine_snapshot"
            | "tool_atlas_snapshot"
            | "memory_search"
            | "memory_save"
            | "memory_get"
            | "memory_list"
            | "memory_delete"
            | "memory_neighbors"
            | "work_memory"
            | "session_bootstrap"
            | "session_finalize"
            | "skills_recommend"
            | "skills_route"
            | "skills_feedback"
            | "agent_spawn"
            | "agent_session_get"
            | "agent_session_wait"
            | "agent_session_list"
            | "agent_session_reconcile"
            | "ide_snapshot"
            | "ide_command"
            | "pet_state_get"
            | "pet_state_set"
            | "pet_state_ritual"
            | "xiao_shu_action_request"
            | "project_detect"
            | "changes_digest"
            | "git_topology_preflight"
            | "plan_save"
            | "plan_load"
            | "plan_update"
    )
}

fn gemini_lean_tool(tool_name: &str) -> bool {
    // gemini-lean is deliberately collab-free (no forum/presence/ide).
    matches!(
        tool_name,
        "capabilities"
            | "memory_search"
            | "memory_get"
            | "memory_list"
            | "skills_recommend"
            | "skills_route"
            | "skills_feedback"
            | "project_detect"
            | "changes_digest"
            | "git_topology_preflight"
            | "mcp_dispatch_audit"
            | "mcp_lifecycle_digest"
            | "readiness_audit"
            | "event_spine_snapshot"
            | "tool_atlas_snapshot"
            | "session_bootstrap"
            | "pet_state_get"
    )
}

fn hook_lifecycle_tool(tool_name: &str) -> bool {
    matches!(
        tool_name,
        "capabilities"
            | "mcp_dispatch_audit"
            | "mcp_lifecycle_digest"
            | "readiness_audit"
            | "event_spine_snapshot"
            | "tool_atlas_snapshot"
            | "memory_compact"
            | "session_bootstrap"
            | "session_curate"
            | "session_finalize"
            | "session_lifecycle_step"
            | "work_memory"
            | "pet_state_get"
            | "pet_state_set"
            | "pet_state_ritual"
    )
}

/// (d) Cross-profile divergence audit. For each named-allowlist profile and
/// each collab capability group, report full / partial / none coverage.
/// **Partial coverage is a drift smell** — it means the profile lists some
/// members of a group by name but not all, which is exactly how `forum_digest`
/// went missing from codex clients. Surfaced in `mcp_config_audit` and pinned
/// by `collab_groups_no_partial_coverage` test.
fn collab_group_divergence() -> Value {
    // (profile-label, name-membership predicate). Tier::Niche forces the
    // name-allowlist path for tier-gated sets (collab tools are never Essential).
    let profiles: [(&str, fn(&str) -> bool); 4] = [
        ("codex-essential", |n| codex_essential_tool(Tier::Niche, n)),
        ("codex-lean", codex_lean_tool),
        ("gemini-lean", gemini_lean_tool),
        ("hook-lifecycle", hook_lifecycle_tool),
    ];
    let group_names: [(&str, &[&str]); 6] = [
        ("forum_read", capgroups::FORUM_READ),
        ("forum_post", capgroups::FORUM_POST),
        ("forum_manage", capgroups::FORUM_MANAGE),
        ("presence_announce", capgroups::PRESENCE_ANNOUNCE),
        ("presence_list", capgroups::PRESENCE_LIST),
        ("ide", capgroups::IDE),
    ];

    let mut rows = Vec::new();
    let mut partial_flags = Vec::new();
    for (plabel, pred) in profiles {
        for (gname, members) in group_names {
            let exposed: Vec<&str> = members.iter().copied().filter(|m| pred(m)).collect();
            let coverage = if exposed.is_empty() {
                "none"
            } else if exposed.len() == members.len() {
                "full"
            } else {
                "partial"
            };
            if coverage == "partial" {
                let missing: Vec<&str> = members.iter().copied().filter(|m| !pred(m)).collect();
                partial_flags.push(json!({
                    "profile": plabel,
                    "group": gname,
                    "exposed": exposed,
                    "missing": missing,
                }));
            }
            rows.push(json!({
                "profile": plabel,
                "group": gname,
                "coverage": coverage,
            }));
        }
    }
    json!({
        "matrix": rows,
        "drift_flags": partial_flags,
        "ok": partial_flags.is_empty(),
        "note": "partial group coverage = a profile lists some-but-not-all members \
                 of a collab group; usually a new tool that wasn't added to the group",
    })
}

fn reg_if(reg: &mut ToolRegistry, policy: ToolPolicy, tier: Tier, tool: Arc<dyn McpTool>) {
    let name = tool.name();
    if policy.includes(tier, name) {
        reg.register(tool);
    }
}

