    #[test]
    fn drift_ratio_first_write_is_zero() {
        // Empty old → first write, no constraint.
        assert_eq!(
            agent_profile_diff_ratio("", "## Identity\n\nI am Claude."),
            0.0
        );
        assert_eq!(agent_profile_diff_ratio("   \n   \n", "anything"), 0.0);
    }

    #[test]
    fn drift_ratio_identical_is_zero() {
        let txt = "## Values\n\n- honesty\n- conservative mutations";
        assert_eq!(agent_profile_diff_ratio(txt, txt), 0.0);
    }

    #[test]
    fn drift_ratio_disjoint_is_one() {
        let old = "line one\nline two\nline three";
        let new = "alpha\nbeta\ngamma";
        assert!((agent_profile_diff_ratio(old, new) - 1.0).abs() < 1e-6);
    }

    #[test]
    fn drift_ratio_partial_change_is_bounded() {
        // 4 old lines, change 1 → ratio ~ 0.4 (1 removed + 1 added) / (4 + 1 union) = 2/5
        let old = "a\nb\nc\nd";
        let new = "a\nb\nc\ne";
        let r = agent_profile_diff_ratio(old, new);
        assert!(r > 0.3 && r < 0.5, "expected ~0.4, got {r}");
    }

    #[test]
    fn drift_ratio_pure_addition_grows_slowly() {
        // 3 old lines, add 1 → 1 new uniqueness, intersection=3, union=4 → 0.25
        let old = "a\nb\nc";
        let new = "a\nb\nc\nd";
        let r = agent_profile_diff_ratio(old, new);
        assert!((r - 0.25).abs() < 1e-6, "expected 0.25, got {r}");
    }

    #[test]
    fn drift_ratio_below_cap_passes() {
        // Add a Growth-marker style entry to a substantial profile.
        let old = (1..=20)
            .map(|i| format!("line {i}"))
            .collect::<Vec<_>>()
            .join("\n");
        let new = format!("{old}\nnew growth marker");
        let r = agent_profile_diff_ratio(&old, &new);
        assert!(r < AGENT_PROFILE_DRIFT_CAP, "expected < cap, got {r}");
    }

    #[test]
    fn drift_ratio_total_rewrite_blocked_by_cap() {
        let old = (1..=10)
            .map(|i| format!("old line {i}"))
            .collect::<Vec<_>>()
            .join("\n");
        let new = (1..=10)
            .map(|i| format!("new line {i}"))
            .collect::<Vec<_>>()
            .join("\n");
        let r = agent_profile_diff_ratio(&old, &new);
        assert!(
            r > AGENT_PROFILE_DRIFT_CAP,
            "total rewrite must exceed cap, got {r}"
        );
    }

    // ── Decision review trigger tests ───────────────────────────────────

    fn mk_decision(key: &str, importance: f64, tags: &[&str], updated_at: i64) -> MemoryRecord {
        MemoryRecord {
            key: key.into(),
            kind: "decision".into(),
            content: format!("First line for {key}.\nMore detail here."),
            tags: tags.iter().map(|s| s.to_string()).collect(),
            related_keys: Vec::new(),
            scope: None,
            created_at: updated_at,
            updated_at,
            last_accessed_at: updated_at,
            access_count: 0,
            importance,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        }
    }

    // ── ζ-11 compute_link_suggestions blacklist tests ──────────────────

    fn mk_mem(key: &str, kind: &str, content: &str, tags: &[&str]) -> MemoryRecord {
        MemoryRecord {
            key: key.into(),
            kind: kind.into(),
            content: content.into(),
            tags: tags.iter().map(|s| s.to_string()).collect(),
            related_keys: Vec::new(),
            scope: None,
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance: 0.5,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        }
    }

    fn mk_mem_scoped(
        key: &str,
        kind: &str,
        content: &str,
        tags: &[&str],
        scope: Option<&str>,
    ) -> MemoryRecord {
        let mut rec = mk_mem(key, kind, content, tags);
        rec.scope = scope.map(|s| s.to_string());
        rec
    }

    fn mk_search_hit_scoped(key: &str, scope: Option<&str>, score: f64) -> MemorySearchHit {
        MemorySearchHit {
            record: mk_mem_scoped(key, "lesson", "content content content content", &[], scope),
            score,
            cosine: Some(score as f32),
        }
    }

    fn mk_edge(from_key: &str, to_key: &str, edge_type: &str) -> MemoryEdge {
        MemoryEdge {
            from_key: from_key.into(),
            to_key: to_key.into(),
            edge_type: edge_type.into(),
            weight: 1.0,
        }
    }

    fn bucket_pairs(got: &Value, bucket: &str) -> u64 {
        got["bucket_counts"]
            .as_array()
            .and_then(|rows| {
                rows.iter()
                    .find(|row| row["bucket"].as_str() == Some(bucket))
            })
            .and_then(|row| row["pairs"].as_u64())
            .unwrap_or(0)
    }

    #[test]
    fn memory_related_keys_preflight_classifies_explicit_links() {
        let mut source = mk_mem_scoped(
            "source",
            "decision",
            "source content with enough detail",
            &[],
            Some("project:/repo"),
        );
        source.related_keys = vec![
            "safe".into(),
            "excluded_kind".into(),
            "missing".into(),
            "cross_scope".into(),
            "already_linked".into(),
            "inactive".into(),
        ];
        let safe = mk_mem_scoped(
            "safe",
            "lesson",
            "safe content with enough detail",
            &[],
            Some("project:/repo"),
        );
        let excluded_kind = mk_mem_scoped(
            "excluded_kind",
            "work_memory",
            "scratch content",
            &[],
            Some("project:/repo"),
        );
        let cross_scope = mk_mem_scoped(
            "cross_scope",
            "decision",
            "other project content",
            &[],
            Some("project:/other"),
        );
        let already_linked = mk_mem_scoped(
            "already_linked",
            "decision",
            "already linked content",
            &[],
            Some("project:/repo"),
        );
        let mut inactive = mk_mem_scoped(
            "inactive",
            "decision",
            "inactive content",
            &[],
            Some("project:/repo"),
        );
        inactive.status = "archived".into();
        let isolated = mk_mem_scoped(
            "isolated",
            "decision",
            "isolated content",
            &[],
            Some("project:/repo"),
        );
        let all = vec![
            source,
            safe,
            excluded_kind,
            cross_scope,
            already_linked,
            inactive,
            isolated,
        ];
        let mut edges_by_key = HashMap::new();
        edges_by_key.insert(
            "source".to_string(),
            vec![mk_edge("source", "already_linked", "relates")],
        );
        let got = memory_related_keys_preflight_from_records(
            &all,
            &edges_by_key,
            &[],
            &["work_memory".to_string()],
            true,
            true,
            None,
            MemorySearchScopeMode::LocalOnly,
            10,
            80,
        );

        assert_eq!(got["visible_total"].as_u64(), Some(5));
        assert_eq!(got["current_orphans"].as_u64(), Some(3));
        assert_eq!(got["candidate_pairs"].as_u64(), Some(1));
        assert_eq!(got["projected_orphans_after_candidates"].as_u64(), Some(2));
        assert_eq!(bucket_pairs(&got, "safe_candidate"), 1);
        assert_eq!(bucket_pairs(&got, "target_excluded_kind"), 1);
        assert_eq!(bucket_pairs(&got, "target_missing"), 1);
        assert_eq!(bucket_pairs(&got, "cross_scope"), 1);
        assert_eq!(bucket_pairs(&got, "already_has_edge"), 1);
        assert_eq!(bucket_pairs(&got, "target_not_active"), 1);
    }

