    #[test]
    fn memory_search_scope_filter_is_strict_by_default() {
        let scoped = mk_mem_scoped(
            "scoped",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/a"),
        );
        let nested = mk_mem_scoped(
            "nested",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/a/sub"),
        );
        let other = mk_mem_scoped(
            "other",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/b"),
        );
        let global = mk_mem_scoped(
            "global",
            "decision",
            "content content content content",
            &[],
            Some("global"),
        );
        let unscoped = mk_mem(
            "unscoped",
            "decision",
            "content content content content",
            &[],
        );

        assert!(memory_search_scope_mode_matches(
            &scoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &nested,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &scoped,
            "project:/repo/a/sub",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &other,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &global,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &unscoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &global,
            "project:/repo/a",
            MemorySearchScopeMode::LocalPlusGlobal
        ));
        assert!(memory_search_scope_mode_matches(
            &unscoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalPlusGlobal
        ));
    }

