    #[test]
    fn recurring_inert_block_caps_items_and_overflow() {
        let now = 1_780_000_000_i64;
        // 4 distinct recurring modes (each 3×); max_items=2 → 2 shown + overflow.
        let mut evs = Vec::new();
        for (src, act, method) in [
            ("browser", "click", "cdp_actionability_probe"),
            ("desktop", "action", "preflight_refusal"),
            ("mobile", "tap", "no_device"),
            ("browser", "click", "css_selector_dispatch"),
        ] {
            for i in 0..3i64 {
                evs.push(mk_sev(src, act, "not_verified", method, None, now - i * 30));
            }
        }
        let block = format_recurring_inert_block(&evs, now, 3, 2).expect("recurring patterns");
        let text = block.join("\n");
        assert!(text.contains("Recurring Inert Patterns (4)"), "{text}");
        assert!(text.contains("… 2 more"), "overflow line: {text}");
        let bullets = text.matches("  • ").count();
        assert_eq!(bullets, 2, "capped to max_items: {text}");
    }

    #[test]
    fn due_review_block_surfaces_overdue_records() {
        let now = 1_780_000_000_i64;
        let rows = vec![
            mk_decision("d_recent", 0.95, &["review:30d"], now - 5 * 86400), // not due
            mk_decision("d_due", 0.92, &["review:30d"], now - 45 * 86400),   // 15d overdue
            mk_decision("d_very_overdue", 0.88, &["review:30d"], now - 120 * 86400), // 90d overdue
        ];
        let block = format_due_review_block(&rows, now).expect("should produce block");
        // Only the two overdue ones present.
        assert!(block.contains("d_due"));
        assert!(block.contains("d_very_overdue"));
        assert!(!block.contains("d_recent"));
        // Most overdue listed first.
        let pos_very = block.find("d_very_overdue").unwrap();
        let pos_due = block.find("d_due").unwrap();
        assert!(
            pos_very < pos_due,
            "most-overdue must come first; got block:\n{block}"
        );
        // Overdue counters are visible.
        assert!(block.contains("overdue 90d"));
        assert!(block.contains("overdue 15d"));
    }

