        tokio::fs::write(
            &script,
            r#"#!/usr/bin/env python3
import json
import sys
print(json.dumps({"schema": "desktop_invoke/v0", "argv": sys.argv[1:]}))
"#,
        )
        .await
        .expect("write script");

