    /// Helper: build a Hub backed by a fresh temp SqliteStore. Returns the
    /// hub plus the temp dir handle (caller drops to clean up).
    async fn mk_test_hub_with_store() -> (crate::Hub, std::path::PathBuf) {
        use std::sync::Arc;
        let temp_dir = std::env::temp_dir().join(format!(
            "ab-session-identity-test-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_nanos()
        ));
        tokio::fs::create_dir_all(&temp_dir).await.expect("mkdir");
        let db_path = temp_dir.join("state.db");
        let store = ab_store::SqliteStore::open(&db_path)
            .await
            .expect("open store");
        let hub = crate::Hub::builder().store(Arc::new(store)).build();
        (hub, temp_dir)
    }

    fn announce_args<'a>(
        node: &'a str,
        project: &'a str,
        role: &'a str,
        pid: i64,
    ) -> ab_store::AgentPresenceUpsert<'a> {
        ab_store::AgentPresenceUpsert {
            name: Some("test-cc"),
            description: None,
            version: None,
            url: None,
            node: Some(node),
            project: Some(project),
            role: Some(role),
            tag: None,
            cwd: None,
            pid: Some(pid),
            capabilities: None,
            skills: None,
        }
    }

    struct EnvVarGuard {
        key: &'static str,
        prev: Option<String>,
    }

    impl EnvVarGuard {
        fn set(key: &'static str, value: &std::path::Path) -> Self {
            let prev = std::env::var(key).ok();
            unsafe {
                std::env::set_var(key, value);
            }
            Self { key, prev }
        }
    }

    impl Drop for EnvVarGuard {
        fn drop(&mut self) {
            unsafe {
                match &self.prev {
                    Some(value) => std::env::set_var(self.key, value),
                    None => std::env::remove_var(self.key),
                }
            }
        }
    }

    fn context_with_session(raw: &str) -> ToolContext {
        ToolContext {
            session_id: Some(SessionId::from_raw(raw.to_string())),
            extras: HashMap::new(),
        }
    }

    static SESSION_IDENTITY_ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    fn lock_session_identity_env() -> std::sync::MutexGuard<'static, ()> {
        SESSION_IDENTITY_ENV_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner())
    }

