    fn mk_cached_with_status(
        key: &str,
        kind: &str,
        emb: Vec<f32>,
        status: &str,
    ) -> (MemoryRecord, Vec<f32>) {
        (
            MemoryRecord {
                key: key.to_string(),
                kind: kind.to_string(),
                content: format!("body of {key}"),
                tags: vec![],
                related_keys: vec![],
                scope: None,
                created_at: 0,
                updated_at: 0,
                last_accessed_at: 0,
                access_count: 0,
                importance: 0.5,
                status: status.into(),
                trigger_pattern: None,
                superseded_by: None,
            },
            emb,
        )
    }

    #[test]
    fn p4_pick_evolution_neighbors_skips_self_and_skill_and_below_threshold() {
        // Self: same key, perfect cosine — must be excluded.
        // Skill: passes threshold, must be excluded.
        // Below threshold: cosine ≈ 0.5, must be excluded.
        // Above threshold + non-skill + different key: must appear, sorted desc.
        let new = vec![1.0_f32, 0.0, 0.0];
        let cache = vec![
            mk_cached("self_dup", "lesson", vec![1.0, 0.0, 0.0]), // self by key
            mk_cached("hot_kin", "lesson", vec![0.95, 0.31, 0.0]),
            mk_cached("warm_kin", "decision", vec![0.80, 0.60, 0.0]),
            mk_cached("cool_kin", "context", vec![0.50, 0.87, 0.0]),
            mk_cached("skill_match", "skill", vec![0.99, 0.14, 0.0]),
        ];
        let picks = pick_evolution_neighbors(&cache, "self_dup", &new, 0.65, 5);
        let keys: Vec<&str> = picks.iter().map(|(rec, _)| rec.key.as_str()).collect();

        assert!(!keys.contains(&"self_dup"), "must exclude self by key");
        assert!(!keys.contains(&"skill_match"), "must exclude kind=skill");
        assert!(!keys.contains(&"cool_kin"), "must exclude below-threshold");
        assert_eq!(keys, vec!["hot_kin", "warm_kin"], "sorted desc by cosine");

        // Top-K cap: even if many would qualify, only k returned.
        let picks_top1 = pick_evolution_neighbors(&cache, "self_dup", &new, 0.65, 1);
        assert_eq!(picks_top1.len(), 1);
        assert_eq!(picks_top1[0].0.key, "hot_kin");
    }

    #[test]
    fn p4_pick_evolution_neighbors_skips_tombstoned_and_superseded() {
        // Phase 2 #1 tombstone-sync regression. memory_delete soft-deletes
        // via status='tombstoned'; cache cleanup is a fire-and-forget
        // tokio::spawn so a tombstoned/superseded record can linger in
        // `cached` after the SQL row was flipped. This test pins the
        // defensive status filter in pick_evolution_neighbors.
        let new = vec![1.0_f32, 0.0, 0.0];
        let cache = vec![
            mk_cached_with_status("active_kin", "lesson", vec![0.95, 0.31, 0.0], "active"),
            mk_cached_with_status(
                "tombstone_kin",
                "lesson",
                vec![0.92, 0.39, 0.0],
                "tombstoned",
            ),
            mk_cached_with_status(
                "superseded_kin",
                "lesson",
                vec![0.88, 0.47, 0.0],
                "superseded",
            ),
        ];
        let picks = pick_evolution_neighbors(&cache, "probe", &new, 0.65, 5);
        let keys: Vec<&str> = picks.iter().map(|(rec, _)| rec.key.as_str()).collect();

        assert_eq!(keys, vec!["active_kin"], "only active records evolve");
    }

