    async fn save_store_trial_memory(hub: &Hub, key: &str, importance: f64, content: &str) {
        let store = hub.store.as_ref().expect("store");
        store
            .memory_save(&ab_store::MemoryRecord {
                key: key.to_string(),
                kind: "fact".to_string(),
                content: content.to_string(),
                tags: vec![],
                related_keys: vec![],
                scope: None,
                created_at: 0,
                updated_at: 0,
                last_accessed_at: 0,
                access_count: 0,
                importance,
                status: String::new(),
                trigger_pattern: None,
                superseded_by: None,
            })
            .await
            .expect("save memory");
    }

