    #[tokio::test]
    async fn session_reflect_is_idempotent_for_same_body_and_focus() {
        // Same focus + same title + same body → identical derived key,
        // so re-running is a memory_save-replace not a duplicate row.
        let (hub, temp_dir) = mk_test_hub_with_store().await;
        let tool = SessionReflectTool::new(hub.clone());
        let ctx = ToolContext::default();

        let args = json!({
            "focus": "decisions",
            "lessons": [
                {"title": "go with cautious v0", "body": "ship conservative magnitudes; calibrate later"}
            ]
        });
        let r1 = tool.execute(args.clone(), &ctx).await.expect("call 1");
        let r2 = tool.execute(args, &ctx).await.expect("call 2");
        let extract = |r: &ab_mcp::ToolResult| -> Value {
            let text = match r.content.first() {
                Some(ab_mcp::ContentBlock::Text { text }) => text.clone(),
                _ => panic!("expected text content"),
            };
            serde_json::from_str(&text).unwrap()
        };
        let v1 = extract(&r1);
        let v2 = extract(&r2);
        let k1 = v1["written"][0]["key"].as_str().unwrap().to_string();
        let k2 = v2["written"][0]["key"].as_str().unwrap().to_string();
        assert_eq!(k1, k2, "same input → same derived key");

        let _ = tokio::fs::remove_dir_all(&temp_dir).await;
    }

    // ── L6 Option E — pure helpers + rate limiter ────────────────────────

    fn option_e_test_hit(key: &str, content: &str, cosine: f32) -> MemoryCosineHit {
        MemoryCosineHit {
            record: ab_store::MemoryRecord {
                key: key.into(),
                kind: "lesson".into(),
                content: content.into(),
                tags: vec![],
                related_keys: vec![],
                scope: None,
                created_at: 0,
                updated_at: 0,
                last_accessed_at: 0,
                access_count: 0,
                importance: 0.5,
                status: String::new(),
                trigger_pattern: None,
                superseded_by: None,
            },
            cosine,
        }
    }

    #[test]
    fn option_e_prompt_includes_all_k_docs_and_query() {
        let hits = vec![
            option_e_test_hit("k1", "alpha body content", 0.9),
            option_e_test_hit("k2", "bravo body content", 0.7),
            option_e_test_hit("k3", "charlie body content", 0.5),
        ];
        let (system, user) = option_e_build_prompt("how does X work", &hits);
        assert!(system.contains("score"), "system must mention scoring");
        assert!(system.contains("verbatim"), "system must require quote");
        assert!(user.contains("how does X work"), "user must echo query");
        for h in &hits {
            assert!(
                user.contains(&h.record.key),
                "user prompt must include doc key {}",
                h.record.key
            );
            // We only assert the first identifying token of the body shows up.
            let first_word = h.record.content.split_whitespace().next().unwrap();
            assert!(
                user.contains(first_word),
                "user prompt must include doc body token {first_word}"
            );
        }
    }

